972: size_t
973: coap_pdu_parse_header_size(coap_proto_t proto,
974:                            const uint8_t *data) {
975:   assert(data);
976:   size_t header_size = 0;
977: 
978:   if (proto == COAP_PROTO_TCP || proto==COAP_PROTO_TLS) {
979:     uint8_t len = *data >> 4;
980:     if (len < 13)
981:       header_size = 2;
982:     else if (len==13)
983:       header_size = 3;
984:     else if (len==14)
985:       header_size = 4;
986:     else
987:       header_size = 6;
988:   } else if (proto == COAP_PROTO_WS || proto==COAP_PROTO_WSS) {
989:     header_size = 2;
990:   } else if (proto == COAP_PROTO_UDP || proto==COAP_PROTO_DTLS) {
991:     header_size = 4;
992:   }
993: 
994:   return header_size;
995: }
