1110: static int
1111: coap_pdu_parse_opt_csm(coap_pdu_t *pdu, uint16_t len) {
1112:   switch ((coap_pdu_signaling_proto_t)pdu->code) {
1113:   case COAP_SIGNALING_CSM:
1114:     switch (pdu->max_opt) {
1115:     case COAP_SIGNALING_OPTION_MAX_MESSAGE_SIZE:
1116:       if (len > 4)
1117:         goto bad;
1118:       break;
1119:     case COAP_SIGNALING_OPTION_BLOCK_WISE_TRANSFER:
1120:       if (len > 0)
1121:         goto bad;
1122:       break;
1123:     case COAP_SIGNALING_OPTION_EXTENDED_TOKEN_LENGTH:
1124:       if (len > 3)
1125:         goto bad;
1126:       break;
1127:     default:
1128:       if (pdu->max_opt & 0x01)
1129:         goto bad; /* Critical */
1130:     }
1131:     break;
1132:   case COAP_SIGNALING_PING:
1133:   case COAP_SIGNALING_PONG:
1134:     switch (pdu->max_opt) {
1135:     case COAP_SIGNALING_OPTION_CUSTODY:
1136:       if (len > 0)
1137:         goto bad;
1138:       break;
1139:     default:
1140:       if (pdu->max_opt & 0x01)
1141:         goto bad; /* Critical */
1142:     }
1143:     break;
1144:   case COAP_SIGNALING_RELEASE:
1145:     switch (pdu->max_opt) {
1146:     case COAP_SIGNALING_OPTION_ALTERNATIVE_ADDRESS:
1147:       if (len < 1 || len > 255)
1148:         goto bad;
1149:       break;
1150:     case COAP_SIGNALING_OPTION_HOLD_OFF:
1151:       if (len > 3)
1152:         goto bad;
1153:       break;
1154:     default:
1155:       if (pdu->max_opt & 0x01)
1156:         goto bad; /* Critical */
1157:     }
1158:     break;
1159:   case COAP_SIGNALING_ABORT:
1160:     switch (pdu->max_opt) {
1161:     case COAP_SIGNALING_OPTION_BAD_CSM_OPTION:
1162:       if (len > 2)
1163:         goto bad;
1164:       break;
1165:     default:
1166:       if (pdu->max_opt & 0x01)
1167:         goto bad; /* Critical */
1168:     }
1169:     break;
1170:   default:
1171:     ;
1172:   }
1173:   return 1;
1174: bad:
1175:   return 0;
1176: }
