1285: static int
1286: write_prefix(char **obp, size_t *len, const char *prf, size_t prflen) {
1287:   /* Make sure space for null terminating byte */
1288:   if (*len < prflen +1) {
1289:     return 0;
1290:   }
1291: 
1292:   memcpy(*obp, prf, prflen);
1293:   *obp += prflen;
1294:   *len -= prflen;
1295:   return 1;
1296: }
