140: COAP_STATIC_INLINE int
141: opt_finished(coap_opt_iterator_t *oi) {
142:   assert(oi);
143: 
144:   if (oi->bad || oi->length == 0 ||
145:       !oi->next_option || *oi->next_option == COAP_PAYLOAD_START) {
146:     oi->bad = 1;
147:   }
148: 
149:   return oi->bad;
