350: size_t
351: coap_opt_encode_size(uint16_t delta, size_t length) {
352:   size_t n = 1;
353: 
354:   if (delta >= 13) {
355:     if (delta < 269)
356:       n += 1;
357:     else
358:       n += 2;
359:   }
360: 
361:   if (length >= 13) {
362:     if (length < 269)
363:       n += 1;
364:     else
365:       n += 2;
366:   }
367: 
368:   return n + length;
369: }
